//! Exact generated-coordinator recovery. Only the retained nonce/IDs and fixed
//! generated bytes are accepted; no arbitrary user cloud target is an argument.
#[cfg(all(windows, feature = "native-sync", feature = "native-test-hooks"))]
fn run() -> anyhow::Result<()> {
    use anyhow::{Context, ensure};
    use std::{fs, path::PathBuf};
    use twodrive_dev::{
        model::CloudBackend,
        native_coordinator::NativeCoordinator,
        onedrive::{self, OneDrive},
    };
    let mut args = std::env::args_os().skip(1);
    let mode = args
        .next()
        .context("--probe or --retire-generated-scope required")?;
    ensure!(
        mode == "--probe" || mode == "--retire-generated-scope",
        "unknown recovery mode"
    );
    let requested = PathBuf::from(args.next().context("retained generated state required")?);
    let expected = args
        .next()
        .context("expected personal owner required")?
        .to_string_lossy()
        .into_owned();
    ensure!(
        args.next().is_none() && requested.is_absolute(),
        "invalid recovery arguments"
    );
    let private = requested.canonicalize()?;
    ensure!(
        private.parent() == Some(std::env::temp_dir().canonicalize()?.as_path())
            && private.file_name().is_some_and(|name| name
                .to_string_lossy()
                .starts_with("twodrive-coordinator-cloud-")),
        "recovery outside generated state"
    );
    let scope: serde_json::Value = serde_json::from_slice(&fs::read(private.join("scope.json"))?)?;
    let name = scope["scope"].as_str().context("scope receipt missing")?;
    let nonce = name
        .strip_prefix("TwoDrive-native-coordinator-validation-")
        .context("foreign scope prefix")?;
    ensure!(
        nonce.len() == 32
            && nonce.bytes().all(|b| b.is_ascii_hexdigit())
            && scope["generated_only"] == true,
        "foreign scope receipt"
    );
    let root = PathBuf::from(
        scope["native_root"]
            .as_str()
            .context("native receipt missing")?,
    );
    ensure!(
        root.is_absolute()
            && root.file_name().is_some_and(|name| name
                .to_string_lossy()
                .starts_with("twodrive-cfapi-fixture-office-coordinator-")),
        "foreign native fixture"
    );
    let provider = OneDrive::open(&private.join("account"), true)?;
    let identity = provider.graph.readonly_identity(&mut || Ok(()))?;
    ensure!(
        identity.account.eq_ignore_ascii_case(&expected),
        "recovery account mismatch"
    );
    let base = format!("/{name}");
    let mut directories = Vec::new();
    if let Some(folder) = provider.get_metadata_by_path(&base)? {
        ensure!(folder.is_dir, "generated scope changed kind");
        directories.push(folder);
        let mut next = 0;
        while next < directories.len() {
            ensure!(
                directories.len() <= 4,
                "unexpected generated directory count"
            );
            for entry in provider
                .graph
                .desktop_directory(&directories[next].path, &mut || Ok(()))?
            {
                ensure!(
                    entry.path.starts_with(&format!("{base}/")),
                    "foreign recovery child"
                );
                if entry.is_dir {
                    ensure!(
                        ["renamed-child", "generated-child", "generated-late-child"]
                            .contains(&entry.name.as_str()),
                        "unexpected generated directory"
                    );
                    directories.push(entry);
                } else {
                    ensure!(
                        ["generated.txt", "renamed.txt", "generated-backup.wbk"]
                            .contains(&entry.name.as_str()),
                        "unexpected generated file"
                    );
                    let bytes = provider.download(&entry.remote_id)?;
                    ensure!(bytes==b"generated coordinator complete bytes through native directory ordering" || bytes==b"generated retained backup replacement target","unexpected generated bytes");
                    ensure!(
                        mode == "--retire-generated-scope",
                        "generated file remains; probe refuses mutation"
                    );
                    provider.graph.delete_item_bound(
                        &identity,
                        &entry.remote_id,
                        &entry.etag,
                        &mut || Ok(()),
                    )?;
                }
            }
            next += 1;
        }
    }
    directories.sort_by_key(|entry| std::cmp::Reverse(entry.path.matches('/').count()));
    for directory in directories {
        let parent = provider
            .get_metadata_by_path(&directory.parent_path)?
            .context("generated parent missing")?;
        match provider.graph.empty_directory_version_bound(
            &identity,
            &directory.remote_id,
            &parent.remote_id,
            &directory.path,
            &mut || Ok(()),
        ) {
            Ok(Some(stamp)) => {
                println!("generated-directory: empty-object-version-ready");
                if mode == "--retire-generated-scope" {
                    provider.graph.delete_item_bound(
                        &identity,
                        &stamp.remote_id,
                        &stamp.etag,
                        &mut || Ok(()),
                    )?;
                }
            }
            Ok(None) => {
                println!("generated-directory: nonempty");
                ensure!(mode == "--probe", "generated directory is not empty");
            }
            Err(error) => {
                let message = error.to_string();
                if message.starts_with("bound empty-directory") || message.starts_with("directory ")
                {
                    eprintln!("{message}");
                }
                return Err(error);
            }
        }
    }
    if mode == "--retire-generated-scope" {
        ensure!(
            provider.get_metadata_by_path(&base)?.is_none(),
            "generated cloud cleanup incomplete"
        );
        let receipt: twodrive_local_files::native::persistent::RootReceipt =
            serde_json::from_slice(&fs::read(private.join("root-receipt.json"))?)?;
        ensure!(
            receipt.identity == b"twodrive-dev-native-v1:generated-office-only",
            "foreign native registration"
        );
        let bridge = onedrive::open_local_session(
            twodrive_core::Database::new(private.join("native.sqlite3")),
            &private.join("cache"),
            &private.join("account"),
            true,
        )?;
        let mut owner = NativeCoordinator::resume(bridge, &root, &receipt)?;
        // The failed phase was after file retirement. Refuse remaining files.
        let mut dirs = vec![owner.root().to_path_buf()];
        let mut index = 0;
        while index < dirs.len() {
            for entry in fs::read_dir(&dirs[index])? {
                let entry = entry?;
                let kind = entry.file_type()?;
                let path = entry.path();
                let canonical = path.canonicalize()?;
                ensure!(
                    kind.is_dir()
                        && !kind.is_symlink()
                        && canonical.starts_with(owner.root())
                        && (entry.file_name() == name
                            || ["renamed-child", "generated-child", "generated-late-child"]
                                .iter()
                                .any(|allowed| entry.file_name() == *allowed)),
                    "native recovery contains an unexpected entry"
                );
                dirs.push(canonical);
            }
            index += 1;
        }
        for dir in dirs.into_iter().rev().filter(|dir| dir != owner.root()) {
            fs::remove_dir(dir)?;
        }
        owner.retire_empty_generated_fixture()?;
        drop(owner);
        fs::remove_dir(root)?;
        println!("generated-recovery: scopes-retired");
    }
    Ok(())
}
#[cfg(all(windows, feature = "native-sync", feature = "native-test-hooks"))]
fn main() {
    if let Err(error) = run() {
        eprintln!("{}", twodrive_backend::diagnostics::safe_error(&error));
        std::process::exit(1);
    }
}
#[cfg(not(all(windows, feature = "native-sync", feature = "native-test-hooks")))]
fn main() {
    eprintln!("requires Windows native-sync/native-test-hooks");
    std::process::exit(2);
}
